"""Replay every complete source screening population and deliberate semantic/capacity refusals on both builds and three JVMs."""
import argparse,json,subprocess,traceback
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from validate_nfcore_engine import BASE,JAVA,JAVA25,DISTRO,linux
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',type=Path,required=True);p.add_argument('--jar21',type=Path,required=True);p.add_argument('--jar25',type=Path,required=True);p.add_argument('--reference',type=Path,required=True);p.add_argument('--expected',type=Path,required=True);p.add_argument('--mutations',type=Path,required=True);a=p.parse_args();out=a.out.resolve();reference=a.reference.resolve();expected=a.expected.resolve();mutations=a.mutations.resolve();assert out.is_relative_to(BASE) and not out.exists();out.mkdir();state=dict(status='FAIL2_NATIVE_EAGER_SCREENING_CONTROLS',new_tool_credit=0,full_eager_adapter_admitted=False,biological_result_admitted=False)
 try:
  measured=json.loads((expected/'COMPLETED.json').read_bytes());assert measured['status']=='PASS_ORIGINAL_MALT_DATABASE_API_AND_ALL_SOURCE_PYSAM_POPULATION_MEASUREMENTS_ONLY';assert pin(expected/'expected-populations.json')==measured['complete_populations'] and pin(expected/'expected-references.json')==measured['references'];adverse=json.loads((mutations/'mutations.json').read_bytes());assert len(adverse)==25 and sum(x['expected']=='refused' for x in adverse)==24;helper=ROOT/'tools/literature/java/NfcoreEagerScreeningReplay.java';guards={str(p):pin(p) for folder in [reference,expected,mutations] for p in folder.rglob('*') if p.is_file()};guards[str(helper)]=pin(helper);guards[str(Path(__file__).resolve())]=pin(Path(__file__).resolve());results=[]
  for compiler in ['21','25']:
   jar=Path(getattr(a,'jar'+compiler)).resolve();guards[str(jar)]=pin(jar);classes=out/('helper'+compiler);classes.mkdir();java=JAVA if compiler=='21' else JAVA25;cmd=[str(java/'javac.exe'),'--release','17','-encoding','UTF-8','-Xlint:all','-Werror','-sourcepath','','-cp',str(jar),'-d',str(classes),str(helper)];r=subprocess.run(cmd,capture_output=True,timeout=90);(out/('javac'+compiler+'.stderr')).write_bytes(r.stderr);assert r.returncode==0,r.stderr
   for runtime in ['windows21','windows25','linux21']:
    label=compiler+'-'+runtime;target=out/label
    if runtime=='linux21':cmd=['wsl.exe','-d',DISTRO,'--exec','/usr/bin/java','-Xmx512m','-cp',linux(classes)+':'+linux(jar),'org.jlinalg.cli.NfcoreEagerScreeningReplay',linux(reference),linux(expected),linux(mutations),linux(target)]
    else:cmd=[str((JAVA if runtime=='windows21' else JAVA25)/'java.exe'),'-Xmx512m','-cp',str(classes)+';'+str(jar),'org.jlinalg.cli.NfcoreEagerScreeningReplay',str(reference),str(expected),str(mutations),str(target)]
    r=subprocess.run(cmd,stdin=subprocess.DEVNULL,capture_output=True,timeout=180);(out/(label+'.stdout')).write_bytes(r.stdout);(out/(label+'.stderr')).write_bytes(r.stderr);save(out/(label+'.process.json'),dict(command=cmd,exit_code=r.returncode));assert r.returncode==0,(label,r.stderr);report=json.loads((target/'COMPLETED.json').read_bytes());assert report['deliberate_refusals']==24 and report['empty_statistics_preserved_absent']==1 and len(report['libraries'])==2;assert sum(x['host']['records'] for x in report['libraries'])==19720 and sum(x['host']['unmapped_queries'] for x in report['libraries'])==16850 and sum(x['malt']['alignments'] for x in report['libraries'])==175;results.append(dict(compiler=compiler,runtime=runtime,complete_libraries=2,deliberate_refusals=24,empty_statistics_preserved_absent=1,report=pin(target/'COMPLETED.json')));print('Complete native screening populations/refusals passed',label,flush=True)
  assert all(pin(Path(p))==v for p,v in guards.items());state.update(status='PASS_12_COMPLETE_NATIVE_SCREENING_LIBRARY_REPLAYS_144_REFUSALS_AND_6_UNASSESSABLE_EMPTY_CONTROLS_ONLY',results=results,complete_library_replays=12,deliberate_refusals=144,empty_statistics_preserved_absent=6,original_population_records=19720,original_unmapped_queries=16850,original_malt_alignments=175,originals_unchanged=guards,scope='Complete supplied host BAM selection, literal unmapped FASTQ identity/orientation/bases/qualities/tags and MALT hard-clip/reference/CIGAR/MD/NM/ZI consistency. No alignment rescoring, LCA assignment, HOPS authenticity, whole eager role or biological admission.')
 except Exception as error:state.update(cause=repr(error),traceback=traceback.format_exc())
 save(out/'COMPLETED.json',state);print(state['status'],state.get('cause',''),flush=True);return 0 if state['status'].startswith('PASS_') else 2
if __name__=='__main__':
 if not __debug__:raise RuntimeError('Never disable complete source/population comparisons')
 raise SystemExit(main())
